set -e
sed -i '' "/it('runs a transition and hands control back to the springs'/,\$d" src/camera/CameraSmoothing.test.ts
cat >> src/camera/CameraSmoothing.test.ts <<'EOF'
  it('runs a transition and hands control back to the springs', () => {
    const rig = new SmoothCameraRig(start);
    rig.transitionTo({ durationSeconds: 0.5, easing: 'linear' });
    expect(rig.transition.isActive).toBe(true);

    let frames = 0;
    while (rig.transition.isActive && frames < 120) {
      rig.update(FRAME, desired);
      frames += 1;
    }
    expect(frames).toBeLessThan(120);
    expect(cameraPoseDistance(rig.current, desired)).toBeLessThan(0.01);

    const moved = createCameraPose({ x: -4, y: 3, z: 0 }, { x: -4, y: 0, z: 0 }, 60);
    for (let i = 0; i < 120; i += 1) rig.update(FRAME, moved);
    expect(rig.current.position.x).toBeCloseTo(moved.position.x, 2);
  });

  it('carries the transition momentum into the springs', () => {
    const rig = new SmoothCameraRig(start);
    rig.transitionTo({ durationSeconds: 0.5, easing: 'linear' });
    for (let i = 0; i < 5; i += 1) rig.update(0.12, desired);
    expect(rig.transition.isActive).toBe(false);

    const fromRest = new SmoothCameraRig(start);
    fromRest.snapTo(rig.current);

    const moved = createCameraPose({ x: -4, y: 3, z: 0 }, { x: -4, y: 0, z: 0 }, 60);
    expect(rig.update(FRAME, moved).position.x).toBeGreaterThan(
      fromRest.update(FRAME, moved).position.x,
    );
  });

  it('pulls the camera in front of blocking geometry', () => {
    const raycaster: CameraRaycaster = { cast: () => ({ distance: 2 }) };
    const blocked = createCameraPose({ x: 0, y: 0, z: 10 }, { x: 0, y: 0, z: 0 }, 55);
    const rig = new SmoothCameraRig(blocked, { raycaster, collision: { clearance: 0.5 } });
    expect(rig.update(FRAME, blocked).position.z).toBeCloseTo(1.5, 6);
  });
});
EOF
npm run typecheck
npm run test:camera
